void DFSUtil(int v, vector<bool>& visited, vector<vector<int>>& adj) {
    visited[v] = true;
    for (int u : adj[v]) {
        if (!visited[u])
            DFSUtil(u, visited, adj);
    }
}
void DFS(int v, vector<vector<int>>& adj) {
    vector<bool> visited(adj.size(), false);
    DFSUtil(v, visited, adj);
}
